#!/usr/bin/env node
import assert from 'node:assert/strict';import fs from 'node:fs';import path from 'node:path';import http from 'node:http';import {spawnSync} from 'node:child_process';import {pathToFileURL,fileURLToPath} from 'node:url';import {createHash} from 'node:crypto';
const baseline=process.env.PDRS_BASELINE??'/Users/da/ws/pilotdeck-rs/resources/PilotDeck',out=path.resolve(process.argv[2]);fs.mkdirSync(out);assert.equal(process.version,'v22.22.0');assert.equal(spawnSync('git',['-C',baseline,'rev-parse','HEAD'],{encoding:'utf8'}).stdout.trim(),'cc7c4e653b15c8b2cec7bcf2d15d41d69396ae85');assert.equal(spawnSync('git',['-C',baseline,'diff','--quiet','HEAD','--','src','packages']).status,0);
const source=path.join(baseline,'src/adapters/channel/bluebubbles/BlueBubblesChannel.ts'),built=path.join(baseline,'dist/src/adapters/channel/bluebubbles/BlueBubblesChannel.js');const sha=p=>createHash('sha256').update(fs.readFileSync(p)).digest('hex');const {default:ts}=await import(pathToFileURL(path.join(baseline,'node_modules/typescript/lib/typescript.js')));const cfg=JSON.parse(fs.readFileSync(path.join(baseline,'tsconfig.json'),'utf8'));const options=ts.convertCompilerOptionsFromJson(cfg.compilerOptions,baseline).options;assert.equal(ts.transpileModule(fs.readFileSync(source,'utf8'),{fileName:source,compilerOptions:{...options,module:ts.ModuleKind.ESNext}}).outputText,fs.readFileSync(built,'utf8'));
for(const key of Object.keys(process.env))delete process.env[key];Object.assign(process.env,{HOME:path.join(out,'home'),PILOT_HOME:path.join(out,'pilot'),PATH:''});fs.mkdirSync(process.env.HOME);fs.mkdirSync(process.env.PILOT_HOME);
const {BlueBubblesChannel}=await import(pathToFileURL(built));let delivered=false,entered=false,exited=false,release;const held=new Promise(resolve=>release=resolve);const submits=[],posts=[],logs=[];
const server=http.createServer(async(req,res)=>{let body='';for await(const chunk of req)body+=chunk;if(req.method==='GET'){res.setHeader('content-type','application/json');res.end(JSON.stringify({data:delivered?[]:[{guid:'message',chatGuid:'chat',text:'held message',dateCreated:1}]}));delivered=true;}else{posts.push({method:req.method,path:req.url,body:JSON.parse(body)});res.end('{}');}});await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));
const adapter=new BlueBubblesChannel({serverUrl:`http://127.0.0.1:${server.address().port}`,password:'fixture'});const handle=await adapter.start({logger:{info:s=>logs.push(['info',s.replaceAll(String(server.address().port),'<port>')]),error:s=>logs.push(['error',s])},gateway:{async *submitTurn(input){submits.push(input);entered=true;try{await held;yield{type:'assistant_text_delta',text:'late'};}finally{exited=true;}}}});
const wait=async pred=>{const end=Date.now()+2000;while(!pred()&&Date.now()<end)await new Promise(r=>setTimeout(r,5));assert.ok(pred());};
try{await wait(()=>entered);await handle.stop('disable');await new Promise(r=>setTimeout(r,25));assert.equal(exited,false);assert.equal(posts.length,0);const afterStop={entered,exited,running:adapter.running,posts:posts.length};release();await wait(()=>exited);assert.equal(posts.length,0);fs.writeFileSync(path.join(out,'oracle.json'),JSON.stringify({boundary:'actual TS start/poll/stop + real loopback HTTP; scripted held Gateway generator, not formal server/provider SSE',submits,afterStop,afterRelease:{exited,posts:posts.length},logs},null,2)+'\n');}finally{release();await handle.stop('cleanup');server.closeAllConnections();await new Promise(resolve=>server.close(resolve));}
fs.writeFileSync(path.join(out,'identity.json'),JSON.stringify({node:process.version,sourceSha256:sha(source),distSha256:sha(built),driverSha256:sha(fileURLToPath(import.meta.url)),revision:'cc7c4e653b15c8b2cec7bcf2d15d41d69396ae85'},null,2)+'\n');console.log(JSON.stringify({passed:true,sha256:sha(path.join(out,'oracle.json'))}));
